import { createDirectus, rest, staticToken, createItem } from '@directus/sdk';

const directus = createDirectus(process.env.DIRECTUS_URL || 'http://directus:8055')
  .with(staticToken(process.env.DIRECTUS_ADMIN_TOKEN || ''))
  .with(rest());

export async function seed() {
  const d = await directus.request(createItem('directus_dashboards', { name: 'Executive Dashboard', icon: 'insights' }));
  await directus.request(createItem('directus_panels', { dashboard: d.id, name: 'Monthly GMV', type: 'metric', width: 6, height: 6, options: { collection: 'orders', aggregate: { function: 'sum', field: 'total_amount' } } }));
}
